return ['domain'=>'zinn-backups','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'hu_HU','project-id-version'=>'zinn-backups','pot-creation-date'=>'2026-10-08T09:17:23+00:00','po-revision-date'=>'2026-10-08T09:17:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Backups'=>'Zinn® Backups','https://zinndigital.com/wordpress-plugins/zinn-backups'=>'https://zinndigital.com/wordpress-plugins/zinn-backups','Backs up your WordPress files and database to your own storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 or any S3-compatible bucket — restores them in one go, and imports backups made by other backup and migration plugins.'=>'Biztonsági mentést készít a WordPress fájlokról és adatbázisról a saját tárhelyre – Dropbox, Google Drive, Cloudflare R2, Amazon S3 vagy bármilyen S3-kompatibilis tároló –, egyszerre visszaállítja őket, valamint importálja a más biztonsági mentési és költöztető bővítmények által készített mentéseket.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Backups'=>'Biztonsági mentések','Get Pro: schedules, several storages, encryption'=>'Váltson Pro verzióra: ütemezések, több tárhely, titkosítás','Working…'=>'Feldolgozás…','Finished'=>'Befejezve','Failed'=>'Sikertelen','Cancelled'=>'Törölve','Cancel'=>'Mégse','Restore'=>'Visszaállítás','Delete'=>'Törlés','Delete this backup from your storage? This cannot be undone.'=>'Törli ezt a biztonsági mentést a tárhelyről? Ez a művelet nem vonható vissza.','No backups yet. Press “Back up now” to make the first one.'=>'Még nincsenek biztonsági mentések. Az első létrehozásához kattintson a „Biztonsági mentés most” gombra.','Reading your storage…'=>'Tárhely beolvasása…','a complete backup, as opposed to an incremental oneFull backup'=>'Teljes biztonsági mentés','a backup holding only what changed since an earlier oneIncremental backup'=>'Növekményes biztonsági mentés','Encrypted'=>'Titkosított','From another site'=>'Másik webhelyről','Database'=>'Adatbázis','Files'=>'Fájlok','Uploading %1$s: %2$s%%'=>'%1$s feltöltése: %2$s%%','Sign in to Dropbox in the window that opened, then paste the code Dropbox shows you:'=>'Jelentkezzen be a Dropboxba a megnyílt ablakban, majd illessze be a Dropbox által megjelenített kódot:','Saved.'=>'Mentve.','Remove this destination from the plugin? The backups stored in it are not deleted.'=>'Eltávolítja ezt a célhelyet a bővítményből? A benne tárolt biztonsági mentések nem törlődnek.','Reload the page to see the restored site.'=>'Az oldal újratöltésével tekinthető meg a helyreállított webhely.','Storage'=>'Tárhely','Import & migrate'=>'Importálás és migrálás','Settings'=>'Beállítások','Sections'=>'Szakaszok','Google Drive is connected.'=>'A Google Drive csatlakoztatva van.','Google Drive could not be connected.'=>'A Google Drive nem csatlakoztatható.','Details'=>'Részletek','Back up now'=>'Biztonsági mentés készítése most','Backups go to your own storage, not this server. <a href="%s">Connect your storage</a> first.'=>'A biztonsági mentések a saját tárhelyre kerülnek, nem erre a szerverre. Először <a href="%s">csatlakoztatni kell a saját tárhelyet</a>.','What to back up'=>'Biztonsági mentés tartalma','Files and database'=>'Fájlok és adatbázis','Database only'=>'Csak adatbázis','Files only'=>'Csak fájlok','Note (optional)'=>'Megjegyzés (opcionális)','Each part is uploaded to your storage and removed from this server before the next one is made, so the backup never takes up room on your hosting.'=>'Minden rész feltöltésre kerül a tárhelyre és törlődik erről a szerverről a következő elkészítése előtt, így a biztonsági mentés soha nem foglal helyet a webtárhelyen.','Your backups'=>'Biztonsági másolatok','Refresh'=>'Frissítés','Restore this backup'=>'Biztonsági mentés visszaállítása','Passphrase'=>'Jelmondat','I understand this replaces this site’s files and database with the backup’s. Files that are not in the backup are kept.'=>'Tudomásul veszem, hogy ez a művelet lecseréli a webhely fájljait és adatbázisát a biztonsági mentésben lévőkre. A biztonsági mentésben nem szereplő fájlok megmaradnak.','Recent activity'=>'Legutóbbi tevékenység','Backup'=>'Biztonsági mentés','Restore / import'=>'Visszaállítás / importálás','Running'=>'Fut','Your storage'=>'Tárhely' . "\0" . 'Tárolási célhelyek','No storage yet. Choose where your backups go below.'=>'Még nincs tárhely. Válassza ki alább, hová kerüljenek a biztonsági mentések.','Ready'=>'Kész','Not connected'=>'Nincs kapcsolódva','Connect'=>'Kapcsolódás','Test'=>'Teszt','Edit'=>'Szerkesztés','Remove'=>'Eltávolítás','Add storage'=>'Tárhely hozzáadása','Backups go to one storage destination. To use a different one, edit or remove the one above.'=>'A biztonsági mentések egy tárolási helyre kerülnek. Másik használatához módosítani vagy törölni kell a fentit.','Kind of storage'=>'Tárhely típusa','Name (for you)'=>'Név (saját részre)','Provider'=>'Szolgáltató','Cloudflare account id'=>'Cloudflare fiókazonosító','Endpoint address'=>'Végpont címe','Region'=>'Régió','Bucket'=>'Tároló','Access key id'=>'Hozzáférési kulcs azonosítója','Secret access key'=>'Titkos hozzáférési kulcs','Leave empty to keep the saved key'=>'Hagyja üresen a mentett kulcs megtartásához','For Cloudflare R2: in the Cloudflare dashboard open R2, create a bucket, then “Manage R2 API tokens” → create a token with Object Read & Write for that bucket, and copy the access key id and secret here.'=>'Cloudflare R2 esetén: a Cloudflare vezérlőpultján nyissuk meg az R2-t, hozzunk létre egy bucketet, majd „Manage R2 API tokens” → hozzunk létre egy tokent Object Read & Write jogosultsággal ahhoz a buckethez, és másoljuk ide az access key id-t és a secretet.','Dropbox app key'=>'Dropbox-alkalmazáskulcs','Create an app at dropbox.com/developers/apps (Scoped access, App folder) with the files.content.read, files.content.write and files.metadata.read permissions, and copy its App key here. Save, then press Connect.'=>'Hozzon létre egy alkalmazást a dropbox.com/developers/apps címen (Scoped access, App folder) a files.content.read, files.content.write és files.metadata.read jogosultságokkal, és másolja ide az App key értékét. Mentse, majd nyomja meg a Connect gombot.','OAuth client id'=>'OAuth kliensazonosító','OAuth client secret'=>'OAuth ügyféltitok','Leave empty to keep the saved secret'=>'Hagyja üresen a mentett titok megtartásához','In Google Cloud Console, enable the Google Drive API, then create an OAuth client of type “Web application” with this address as an authorised redirect URI:'=>'A Google Cloud Console felületén engedélyezze a Google Drive API-t, majd hozzon létre egy „Web application” típusú OAuth-klienst ezzel a címmel mint engedélyezett átirányítási URI-val:','Save, then press Connect. The plugin only sees the files it creates.'=>'Mentés, majd kattintás a Csatlakozás gombra. A bővítmény csak az általa létrehozott fájlokat látja.','Folder inside the storage (optional)'=>'Mappa a tárhelyen belül (nem kötelező)','Save storage'=>'Tárhely megtakarítása','Import a backup from another plugin or host'=>'Biztonsági mentés importálása másik bővítményből vagy tárhelyről','Bring a site in from a backup made by UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, or any zip/tar archive of a WordPress site with its .sql dump. The content goes into wp-content and the database replaces this site’s; addresses are changed to this site’s automatically.'=>'Honlap importálása az UpdraftPlus, az All-in-One WP Migration (.wpress), a Duplicator (zip), a BackWPup, a WPvivid, a Jetpack VaultPress Backup, a BlogVault, a Zinn® Migrate által készített biztonsági mentésből, vagy egy WordPress honlap .sql dump fájlt tartalmazó bármely zip/tar archívumából. A tartalom a wp-content könyvtárba kerül, az adatbázis pedig felváltja az ezen a honlapon lévőt; a címek automatikusan az ezen a honlapon lévőkre módosulnak.','Upload from your computer'=>'Feltöltés a számítógépről','Choose every file of the backup at once (UpdraftPlus makes several). Large files are sent in small pieces, so your host’s upload limit does not apply.'=>'Válasszuk ki a biztonsági mentés minden fájlját egyszerre (az UpdraftPlus többet is készít). A nagy fájlok kis darabokban kerülnek elküldésre, így a tárhely feltöltési korlátja nem érvényesül.','Or from links (Google Drive, Dropbox or any download address)'=>'Vagy hivatkozásokból (Google Drive, Dropbox vagy bármilyen letöltési cím)','One link per line. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link; turn sharing off again afterwards.'=>'Soronként egy hivatkozás. Google Drive és Dropbox esetén a fájlt a „bárki, aki rendelkezik a linkkel” beállítással kell megosztani, és beilleszteni a hivatkozást; a megosztást utána kapcsolja ki újra.','Or a file already on this server'=>'Vagy egy, a kiszolgálón már megtalálható fájl','Upload archives by FTP or your host’s file manager into %s and reload this page.'=>'Töltsön fel archívumokat FTP-n vagy a tárhely fájlkezelőjén keresztül a(z) %s mappába, majd frissítse ezt az oldalt.','Or a deploy code from another site'=>'Vagy egy telepítési kód egy másik webhelyről','If another site gave you a Zinn® Backups deploy code, paste it here to copy that backup onto this site without sharing its storage keys. A code works for a few hours; treat it like a password.'=>'Ha egy másik webhelyről származik egy Zinn® Backups telepítési kód, illessze be ide a biztonsági mentés átmásolásához a tárhelykulcsok megosztása nélkül. A kód néhány óráig érvényes; kezelje jelszóként.','Passphrase (only if that backup is encrypted)'=>'Jelmondat (csak akkor, ha a biztonsági mentés titkosított)','Import'=>'Importálás','I understand the import replaces this site’s content and database. After it, sign in with an account from the imported site.'=>'Tudomásul veszem, hogy az importálás felülírja a webhely tartalmát és adatbázisát. Ezt követően bejelentkezés szükséges az importált webhely egyik fiókjával.','Moving to Zinn® hosting?'=>'Átköltözés a Zinn® webtárhelyére?','Zinn Digital® can move your site for you from your old host. If your old host gives you no FTP, SSH or control-panel access, install Zinn® Migrate on the old site; it makes one archive you can import here or hand to Zinn®.'=>'A Zinn Digital® át tudja költöztetni a webhelyet a régi tárhelyszolgáltatótól. Ha a régi szolgáltató nem biztosít FTP-, SSH- vagy vezérlőpult-hozzáférést, telepíteni kell a Zinn® Migrate bővítményt a régi webhelyre; ez létrehoz egy archívumot, amelyet importálni lehet ide, vagy át lehet adni a Zinn® csapatának.','What goes into a backup'=>'Mit tartalmaz a biztonsági mentés','Include WordPress’s own files (wp-admin, wp-includes). Usually not needed: WordPress can always be reinstalled.'=>'A WordPress saját fájljainak belefoglalása (wp-admin, wp-includes). Általában nem szükséges: a WordPress bármikor újratelepíthető.','Also leave out these folders or files (one per line, relative to the WordPress folder)'=>'Hagyja ki ezeket a mappákat vagy fájlokat is (soronként egyet, a WordPress mappához viszonyítva)','Always left out: caches, update scratch space, and other backup plugins’ own archive folders:'=>'Mindig kimarad: gyorsítótárak, frissítési ideiglenes terület és más biztonsági mentési bővítmények saját archívum mappái:','Size of each part (MB)'=>'Az egyes részek mérete (MB)','Save settings'=>'Beállítások mentése','A backup part could not be opened for writing. Check that wp-content has free space.'=>'A biztonsági mentés egyik részét nem sikerült megnyitni írásra. Ellenőrizze, hogy a wp-content könyvtárban van-e szabad hely.','A backup part could not be written. Check that wp-content has free space.'=>'A biztonsági mentés egyik részét nem sikerült írni. Ellenőrizze, hogy a wp-content könyvtárban van-e szabad hely.','Connect a storage destination on the Storage tab first: backups are kept in your own storage, not on this server.'=>'Először csatlakoztasson egy tárolási célhelyet a Storage lapon: a biztonsági mentések a saját tárhelyen tárolódnak, nem ezen a kiszolgálón.','Multisite networks are not supported yet.'=>'A többhelyes (Multisite) hálózatok még nem támogatottak.','This server’s PHP has no ZipArchive extension. Ask your host to enable it.'=>'A kiszolgáló PHP-verziójában nem található meg a ZipArchive kiterjesztés. Kérje meg a tárhelyszolgáltatót az engedélyezésére.','Starting'=>'Indítás folyamatban','Listing files'=>'Fájlok listázása','Backing up the database'=>'Adatbázis biztonsági mentése folyamatban','Packing files'=>'Fájlok becsomagolása','Uploading to your storage'=>'Feltöltés a tárhelyre','Finishing'=>'Befejezés','The backup reached an unknown stage.'=>'A biztonsági mentés ismeretlen szakaszba ért.','Backup %s started.'=>'%s biztonsági mentése elindult.','Found %1$s files (%2$s).'=>'%1$s fájl található (%2$s).','Database: %1$d tables, %2$s rows, %3$s compressed.'=>'Adatbázis: %1$d tábla, %2$s sor, %3$s tömörítve.','Backup complete: %1$s stored in %2$d destination.'=>'Biztonsági mentés kész: %1$s tárolva %2$d célhelyen.' . "\0" . 'Biztonsági mentés kész: %1$s elmentve %2$d helyre.','Some parts already uploaded could not be removed from your storage; they are in an incomplete backup folder and are never offered for restore.'=>'Néhány már feltöltött részt nem sikerült eltávolítani a tárhelyről; ezek egy befejezetlen biztonsági mentési mappában találhatók, és soha nem jelennek meg helyreállításra.','A storage destination was removed while the backup was running.'=>'Egy tárolási célhely eltávolításra került a biztonsági mentés futása közben.','That is not a backup folder.'=>'Ez nem biztonsági mentési mappa.','That storage destination is no longer saved on this site.'=>'Ez a tárolási célhely már nincs elmentve ezen az oldalon.','Later incremental backups are built on this one. Delete those first.'=>'A későbbi növekményes biztonsági mentések erre épülnek. Először azokat törölje.','This file is not an encrypted Zinn® Backups file.'=>'Ez a fájl nem egy titkosított Zinn® Backups fájl.','The backup could not be decrypted: the passphrase is wrong or the file is damaged.'=>'A biztonsági mentést nem sikerült visszafejteni: a jelmondat helytelen, vagy a fájl sérült.','The encrypted backup file is incomplete.'=>'A titkosított biztonsági mentési fájl nem teljes.','The database file could not be written. Check that wp-content has free space.'=>'Az adatbázisfájl írása nem sikerült. Ellenőrizendő, hogy a wp-content könyvtárban van-e szabad hely.','That is not a deploy code. A deploy code starts with zbdeploy1.'=>'Ez nem telepítési kód. A telepítési kód a zbdeploy1 karakterekkel kezdődik.','That deploy code is damaged. Copy it again from the other site.'=>'A telepítési kód sérült. Másolja ki újra a másik webhelyről.','The deploy code has expired or its backup was deleted. Make a new code on the other site.'=>'A közzétételi kód lejárt, vagy a biztonsági mentése törölve lett. Hozzon létre egy új kódot a másik webhelyen.','That deploy code does not point at a Zinn® Backups backup.'=>'Ez a telepítési kód nem egy Zinn® Backups biztonsági mentésre mutat.','The deploy code has expired. Make a new code on the other site.'=>'A közzétételi kód lejárt. Hozzon létre egy új kódot a másik webhelyen.','The server stopped honouring partial downloads. Start the import again.'=>'A kiszolgáló nem támogatja tovább a részleges letöltéseket. Az importálást újra kell indítani.','The link opened a web page instead of a file. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link.'=>'A hivatkozás egy weboldalt nyitott meg fájl helyett. Google Drive és Dropbox esetén a fájlt a „bárki, aki rendelkezik a linkkel” beállítással osszuk meg, és illesszük be ezt a linket.','The link answered with HTTP %d.'=>'A hivatkozás válasza HTTP %d volt.','The file list could not be written.'=>'A fájllistát nem sikerült kiírni.','The storage service could not be reached: %s'=>'A tárhelyszolgáltatás nem érhető el: %s','%1$s answered with HTTP %2$d: %3$s'=>'%1$s válasza a következő HTTP %2$d hibakóddal érkezett: %3$s','no details given'=>'Nincsenek megadva részletek','You are not allowed to manage backups.'=>'A biztonsági mentések kezelése nem engedélyezett.','Tick the box to confirm that the restore replaces this site’s files and database.'=>'A négyzet bejelölésével megerősíthető, hogy a visszaállítás felülírja a webhely fájljait és adatbázisát.','Save the destination first.'=>'Előbb a cél mentése szükséges.','Connected: a test file was written and removed.'=>'Csatlakozva: a tesztfájl kiírásra és törlésre került.','Enter the app key of your Dropbox app first (see the steps beside the form).'=>'Először adja meg a Dropbox alkalmazás alkalmazáskulcsát (lásd az űrlap melletti lépéseket).','This kind of storage does not sign in.'=>'Ez a fajta tárhely nem jelentkezik be.','The sign-in expired. Press Connect again.'=>'A bejelentkezés lejárt. Nyomja meg újra a Csatlakozás gombot.','Dropbox is connected.'=>'A Dropbox csatlakoztatva van.','Settings saved.'=>'Beállítások elmentve.','Another backup, restore or import is running. Wait for it to finish, or cancel it.'=>'Egy másik biztonsági mentés, visszaállítás vagy importálás van folyamatban. Várjon, amíg befejeződik, vagy szakítsa meg a folyamatot.','The upload was not started properly. Start again.'=>'A feltöltés nem indult el megfelelően. Próbálja újra a kezdéstől.','The chunk did not arrive. Your server may limit upload sizes; try again.'=>'A darab nem érkezett meg. A szerver korlátozhatja a feltöltési méretet; próbálja meg újra.','Tick the box to confirm that the import replaces this site’s content and database.'=>'Jelölje be a négyzetet annak megerősítéséhez, hogy az importálás felülírja a webhely tartalmát és adatbázisát.','Choose an archive to import: upload it, paste a link, or pick one from the import folder.'=>'Archívum kiválasztása az importáláshoz: feltöltés, hivatkozás beillesztése vagy választás az importálási mappából.','Hosting customer? Get %1$d%% off %2$s'=>'Tárhely-ügyfél? Szerezzen %1$d%% kedvezményt a következőből: %2$s','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment. Renewals are at the normal price.'=>'A Zinn Digital® tárhelyszolgáltatás ügyfeleként személyes kód jár, amellyel %d%% kedvezmény érhető el az első fizetésből. A megújítások a normál áron történnek.','Get my %d%% code and go to checkout'=>'A(z) %d%%-os kód kérése és továbblépés a fizetéshez','Sorry, you are not allowed to do that.'=>'Sajnos ez a művelet nem engedélyezett.','This discount is for customers with a paid hosting plan in good standing. Free trials do not qualify.'=>'Ez a kedvezmény a rendezett státuszú, fizetős tárhelycsomaggal rendelkező ügyfelek számára érvényes. Az ingyenes próbaidőszakok nem jogosultak.','You have already used your hosting-customer discount for this plugin.'=>'A tárhelyügyfél-kedvezmény már fel lett használva ehhez a bővítményhez.','We could not get your code just now. Please try again in a few minutes.'=>'A kód lekérése jelenleg nem sikerült. Kérjük, próbálja meg újra néhány perc múlva.','Reading the backup'=>'Biztonsági másolat beolvasása','Downloading the archive'=>'Archívum letöltése','Recognising the archive'=>'Archívum felismerése','Restoring files'=>'Fájlok visszaállítása','Downloading the database'=>'Adatbázis letöltése folyamatban','Restoring the database'=>'Az adatbázis visszaállítása folyamatban','Updating the site address'=>'A webhely címének frissítése','Switching to the restored database'=>'Átváltás a visszaállított adatbázisra','The restore reached an unknown stage.'=>'A visszaállítás ismeretlen szakaszba ért.','This folder has no complete Zinn® Backups backup in it (the manifest is missing).'=>'Ez a mappa nem tartalmaz teljes Zinn® Backups biztonsági mentést (a jegyzék hiányzik).','This backup is encrypted. Enter its passphrase to restore it.'=>'Ez a biztonsági mentés titkosított. A visszaállításhoz meg kell adni a jelmondatot.','This incremental backup needs backup %s, which is no longer in the storage.'=>'Ehhez a növekményes biztonsági mentéshez a(z) %s biztonsági mentés szükséges, amely már nincs a tárhelyen.','Restoring the backup of %1$s (%2$d file parts).'=>'%1$s biztonsági másolatának visszaállítása (%2$d fájlrész).','%1$s file could not be overwritten because this site is not allowed to change it, and was left as it is: %2$s'=>'A(z) %1$s fájlt nem sikerült felülírni, mert ez az oldal nem jogosult a módosítására, így változatlanul maradt: %2$s' . "\0" . '%1$s fájlt nem sikerült felülírni, mert a webhelynek nincs jogosultsága módosítani azokat, így változatlanul maradtak: %2$s','Restored %s files.'=>'%s fájl visszaállítva.','%s did not match its checksum after downloading. The copy in storage may be damaged.'=>'A(z) %s a letöltés után nem egyezett az ellenőrző összegével. Lehet, hogy a tárolóban lévő példány sérült.','%s did not arrive. Upload it again.'=>'A(z) %s nem érkezett meg. Kérjük, töltse fel újra.','Recognised: %s.'=>'Felismerve: %s.','Imported %1$s files into wp-content (%2$s left out: caches, drop-ins and other backup plugins’ folders).'=>'%1$s fájl importálva a wp-content mappába (%2$s kihagyva: gyorsítótárak, drop-in fájlok és más biztonsági mentési bővítmények mappái).','The archive has no database dump, so only files were imported.'=>'Az archívum nem tartalmaz adatbázis-mentést, így csak a fájlok importálása történt meg.','Database restored into %d temporary tables.'=>'Az adatbázis visszaállítva %d ideiglenes táblába.','%s has no WordPress tables in it and was skipped.'=>'A(z) %s nem tartalmaz WordPress táblákat, ezért ki lett hagyva.','The backup’s database has no WordPress tables, so nothing was replaced.'=>'A biztonsági mentés adatbázisa nem tartalmaz WordPress táblákat, így semmi sem került lecserélésre.','This backup is of a multisite network. Restoring a network into a single site is not supported.'=>'Ez a biztonsági mentés egy többhelyes (multisite) hálózatról készült. A hálózat visszaállítása egyetlen webhelyre nem támogatott.','Moving the content from %1$s to %2$s.'=>'Tartalom áthelyezése innen: %1$s ide: %2$s.','Restore complete. If you are signed out, sign in with an account from the restored site.'=>'A visszaállítás befejeződött. Kijelentkezés esetén jelentkezzünk be a visszaállított webhely valamelyik fiókjával.','Restore complete.'=>'Visszaállítás kész.','%1$s — trying again in %2$d seconds.'=>'%1$s — újrapróbálkozás %2$d másodperc múlva.','Cancelled.'=>'Törölve.','Backups go to one storage destination. Edit or remove the one you have to use a different one.'=>'A biztonsági mentések egyetlen tárhelycélra kerülnek. Másik használatához szerkeszteni vagy törölni kell a meglévőt.','The database file could not be opened.'=>'Az adatbázisfájlt nem sikerült megnyitni.','The database refused a statement from the backup: %1$s (%2$s…)'=>'Az adatbázis elutasított egy utasítást a biztonsági mentésből: %1$s (%2$s…)','The restored tables could not be swapped in: %s. Your site is unchanged.'=>'Nem sikerült felcserélni a helyreállított táblákat: %s. A webhely változatlan maradt.','There is no writable folder for temporary backup files. Make wp-content writable and try again.'=>'Nincs írható mappa az ideiglenes biztonsági mentési fájlok számára. Legyen írható a wp-content mappa, majd próbálja újra.','Could not create a folder for this job.'=>'Nem sikerült mappát létrehozni ehhez a feladathoz.','%s — guides and services'=>'%s – útmutatók és szolgáltatások','User guides'=>'Felhasználói útmutatók','Read the %s user guide'=>'A(z) %s felhasználói útmutató elolvasása','Hide this'=>'Ennek elrejtése','Zinn® hosting for WordPress'=>'Zinn® webtárhely a WordPresshez','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, napi biztonsági mentések, ingyenes költöztetés és több webhelyet kezelők számára készült vezérlőpult.','The Zinn® marketplace'=>'A Zinn® piactér','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Vásároljon és adjon el bejáratott webhelyeket, domaineket és linkelhelyezéseket úgy, hogy a pénzt biztonságban tartják, amíg mindkét fél elégedett nem lesz.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — bízzon meg olyan embereket, akik ebből élnek','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Globális szabadúszó piactér: böngésszen több mint 10 000 kész szolgáltatás között íróktól, tervezőktől, fejlesztőktől és SEO szakemberektől, vagy tegyen közzé egy projektet, és várja az ajánlatokat.','See the Zinn Digital® release notes.'=>'A Zinn Digital® kiadási megjegyzéseinek megtekintése.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'A Zinn® frissítési szolgáltatás nem adott ki letöltési hivatkozást ehhez a frissítéshez. Ellenőrizni kell, hogy a webhely eléri-e a Zinn® platformot, majd újra kell próbálni.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'A frissítést nem sikerült letölteni a Zinn® frissítési szolgáltatásból (%s). Próbálkozzunk újra néhány perc múlva.','The downloaded update failed its integrity check and was not installed.'=>'A letöltött frissítés ellenőrző összege érvénytelen, ezért nem került telepítésre.','The zip archive could not be opened. It may be damaged or incomplete.'=>'A zip archívumot nem sikerült megnyitni. Lehet, hogy sérült vagy hiányos.','This .wpress file uses a format we cannot read (it may be compressed or encrypted by All-in-One WP Migration). Export it again without encryption.'=>'Ez a .wpress fájl olyan formátumot használ, amely nem olvasható (lehetséges, hogy az All-in-One WP Migration tömörítette vagy titkosította). Kérjük, exportálja újra titkosítás nélkül.','This is a Duplicator “DupArchive” (.daf) file. In Duplicator, build the package again with the archive format set to ZIP, then import that.'=>'Ez egy Duplicator „DupArchive” (.daf) fájl. A Duplicatorban hozza létre újra a csomagot ZIP formátumot beállítva, majd importálja azt.','This UpdraftPlus database backup is encrypted. Decrypt it in UpdraftPlus (or turn off database encryption and back up again), then import it.'=>'Ez az UpdraftPlus adatbázis-mentés titkosítva van. Fejtse vissza az UpdraftPlusban (vagy kapcsolja ki az adatbázis-titkosítást, és készítsen új mentést), majd importálja.','Database dump'=>'Adatbázis-dump','%s is not a backup archive we can read (zip, tar, tar.gz, .wpress, .sql or .sql.gz).'=>'A(z) %s nem olvasható biztonsági mentési archívum (zip, tar, tar.gz, .wpress, .sql vagy .sql.gz).','Website archive'=>'Webhelyarchívum','%s has no WordPress content (no wp-content folder and no database dump) in it.'=>'A(z) %s nem tartalmaz WordPress-tartalmat (nincs benne wp-content mappa és adatbázis-mentés sem).','This .wpress file is encrypted or compressed by All-in-One WP Migration. Export it again with encryption and compression switched off, then import that.'=>'Ez a .wpress fájl titkosítva vagy tömörítve van az All-in-One WP Migration által. Exportálja újra kikapcsolt titkosítással és tömörítéssel, majd importálja azt.','Other S3-compatible storage'=>'Egyéb S3-kompatibilis tárhely','Cloudflare R2, Amazon S3 or S3-compatible'=>'Cloudflare R2, Amazon S3 vagy S3-kompatibilis','The storage keys could not be read on this site. Enter the secret key again on the Storage tab.'=>'A tárolási kulcsokat nem sikerült beolvasni ezen a webhelyen. Adja meg újra a titkos kulcsot a Tárolás lapon.','This kind of storage is not known.'=>'Ez a fajta tárhely nem ismert.','Choose a kind of storage.'=>'Tárhelytípus kiválasztása.','Enter the bucket name and the access key.'=>'Adja meg a bucket nevét és a hozzáférési kulcsot.','Enter your Cloudflare account id (or the full R2 endpoint).'=>'A Cloudflare-fiókazonosító (vagy a teljes R2 végpont) megadása.','Enter the endpoint address of your storage.'=>'Adja meg a tároló végpontjának címét.','Enter the OAuth client id from your Google Cloud project.'=>'Adja meg az OAuth client id azonosítót a Google Cloud projektből.','Dropbox did not return a refresh token. Start the connection again.'=>'A Dropbox nem adott vissza frissítési tokent. Indítsa újra a kapcsolódást.','Dropbox is not connected. Connect it again on the Storage tab.'=>'A Dropbox nincs csatlakoztatva. Csatlakoztassa újra a Tárhely lapon.','Google did not return a refresh token. Remove this site from your Google account’s third-party access and connect again.'=>'A Google nem adott vissza frissítési tokent. Távolítsuk el ezt a webhelyet a Google-fiók harmadik felek általi hozzáféréséből, majd csatlakozzunk újra.','That file is not in Google Drive any more.'=>'Ez a fájl már nincs a Google Drive-on.','Google Drive is not connected. Connect it again on the Storage tab.'=>'A Google Drive nincs csatlakoztatva. Csatlakoztassa újra a Tárhely lapon.','The storage service did not start the upload.'=>'A tárolási szolgáltatás nem indította el a feltöltést.','The storage service sent a reply that could not be read.'=>'A tárhelyszolgáltatás nem olvasható választ küldött.','A temporary backup file could not be read.'=>'Egy ideiglenes biztonsági mentési fájl nem olvasható.','A deploy link is read-only.'=>'A közzétételi hivatkozás csak olvasható.','The deploy code has no link for a file this backup needs.'=>'A közzétételi kód nem tartalmaz hivatkozást a biztonsági mentéshez szükséges fájlhoz.','The deploy link'=>'A közzétételi hivatkozás']];